'use strict';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',clone=x=>JSON.parse(JSON.stringify(x)),KEY='mit-map-editor-v1';
let data=clone(INITIAL),phase=0,mode='move',selected=null,first=null,history=[],zoom=1,pan={x:0,y:0},drag=null;
try{const saved=localStorage.getItem(KEY);if(saved){data=validate(JSON.parse(saved));if(!localStorage.getItem(KEY+'-before-id-edit'))localStorage.setItem(KEY+'-before-id-edit',saved);$('saved').textContent='已读取原有修改，节点、坐标与连线保持不变；升级前存档已备份。';}}catch{$('saved').textContent='本机存档未能完整读取或备份，请先导出备份。';}
function alignCoordinates(v){v.stages.forEach((s,i)=>{const lookup=Object.fromEntries(INITIAL.stages[i].nodes.map(n=>[n.id,n]));for(const n of s.nodes){const q=lookup[n.id];if(q)for(const k of ['x','y','labelDx','labelDy','positionNote','uncertainPosition'])n[k]=q[k];}});v.coordinateRevision=INITIAL.coordinateRevision;return v;}
function validate(v){if(v?.version!==1||!Array.isArray(v.stages)||v.stages.length!==4)throw Error('需要本编辑器导出的四阶段 JSON');let count=0;for(const s of v.stages){if(!Array.isArray(s.nodes)||!Array.isArray(s.edges)||s.nodes.length>500||s.edges.length>10000)throw Error('节点或连线数据无效');let ids=new Set();for(const n of s.nodes){if(typeof n.id!=='string'||!n.id||n.id.length>60||ids.has(n.id)||typeof n.name!=='string'||n.name.length>80||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.x>310||n.y<0||n.y>207||!['building','plaza','zone'].includes(n.kind))throw Error('节点编号、坐标或类型无效');ids.add(n.id);count++;}const keys=new Set();for(const e of s.edges){const k=[e.a,e.b].sort().join('|');if(e.a===e.b||!ids.has(e.a)||!ids.has(e.b)||keys.has(k))throw Error('存在无效或重复连线');keys.add(k);}}return clone(v);}
const S=()=>data.stages[phase],key=(a,b)=>[a,b].sort().join('|');
function checkpoint(){history.push(clone(data));if(history.length>80)history.shift();}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));$('saved').textContent='已保存到本机 · '+new Date().toLocaleTimeString('zh-CN')+' · 建议导出备份';}catch{$('saved').textContent='浏览器无法自动保存，请使用“导出修改”备份。';}}
function mark(tag,attrs={},text){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e;}
const panels=['0 0 310 207','310 0 310 207','0 207 310 207','310 207 310 207'],names=['Ⅰ 左上图','Ⅱ 右上图','Ⅲ 左下图','Ⅳ 右下图'];
$('photo').setAttribute('href',BASE_IMAGE);
names.forEach((name,i)=>{const b=document.createElement('button');b.type='button';b.dataset.phase=i;const svg=mark('svg',{viewBox:panels[i],'aria-hidden':true});svg.append(mark('image',{href:BASE_IMAGE,width:618,height:414}));b.append(svg);const t=document.createElement('div'),strong=document.createElement('strong'),sub=document.createElement('span');strong.textContent=name;sub.textContent='独立修改';t.append(strong,sub);b.append(t);b.onclick=()=>switchPhase(i);$('phases').append(b);});
function switchPhase(i){phase=i;selected=null;first=null;zoom=1;pan={x:0,y:0};draw();}
function transform(){$('scene').setAttribute('transform',`translate(${pan.x} ${pan.y}) scale(${zoom})`);}
function calc(){let ns=S().nodes,N=ns.length,ds=Array.from({length:N},(_,i)=>Array.from({length:N},(_,j)=>i===j?0:Infinity)),ix=Object.fromEntries(ns.map((n,i)=>[n.id,i]));for(const e of S().edges)ds[ix[e.a]][ix[e.b]]=ds[ix[e.b]][ix[e.a]]=1;for(let k=0;k<N;k++)for(let i=0;i<N;i++)for(let j=0;j<N;j++)ds[i][j]=Math.min(ds[i][j],ds[i][k]+ds[k][j]);let seen=new Set(),c=0,eff=0;for(let i=0;i<N;i++){if(!seen.has(i)){c++;for(let j=0;j<N;j++)if(Number.isFinite(ds[i][j]))seen.add(j);}for(let j=0;j<N;j++)if(i!==j&&Number.isFinite(ds[i][j]))eff+=1/ds[i][j];}return{nodes:N,edges:S().edges.length,components:c,efficiency:N>1?eff/(N*(N-1)):0};}
function draw(){const s=S(),by=Object.fromEntries(s.nodes.map(n=>[n.id,n]));$('base').setAttribute('viewBox',panels[phase]);$('base').style.opacity=$('opacity').value;transform();$('lines').replaceChildren();$('points').replaceChildren();
for(const e of s.edges){const a=by[e.a],b=by[e.b],g=mark('g');for(const cl of ['visible','hit'])g.append(mark('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,class:cl}));g.addEventListener('pointerdown',ev=>{if(mode==='erase'){ev.stopPropagation();checkpoint();s.edges=s.edges.filter(x=>key(x.a,x.b)!==key(e.a,e.b));save();draw();}});$('lines').append(g);}
for(const n of s.nodes){const g=mark('g',{'data-id':n.id,class:(selected===n.id||first===n.id?'selected ':'')+(n.uncertainPosition?'uncertain':''),'aria-label':n.id+' '+n.name});g.append(mark('title',{},n.id+' '+n.name+' · '+(n.positionNote||'手动标注')));g.append(n.kind==='plaza'?mark('rect',{x:n.x-1.6,y:n.y-1.6,width:3.2,height:3.2}):mark('circle',{cx:n.x,cy:n.y,r:1.7}));g.append(mark('text',{x:n.x+(Number(n.labelDx)||0),y:n.y+(Number(n.labelDy)||6),'text-anchor':'middle'},n.id==='12-old'?'12?':n.id));g.addEventListener('pointerdown',e=>onNode(e,n));$('points').append(g);}
$('lines').style.display=$('showEdges').checked?'':'none';$('points').style.display=$('showNodes').checked?'':'none';document.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.phase)===phase));document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));$('stageTitle').textContent=names[phase]+' · 当前图结构';const stats=calc();$('stats').replaceChildren();for(const [label,value] of [['节点',stats.nodes],['连线',stats.edges],['连通分量',stats.components],['全局效率',stats.efficiency.toFixed(3)]]){const d=document.createElement('div');d.textContent=label;const b=document.createElement('b');b.textContent=value;d.append(b);$('stats').append(d);}
const n=by[selected];$('empty').hidden=!!n;$('editor').hidden=!n;if(n){$('nodeId').value=n.id;$('nodeName').value=n.name;$('nodeKind').value=n.kind;}$('positionNote').textContent=n?(n.positionNote||'用户手动标注') : '';for(const id of ['edgeA','edgeB']){const old=$(id).value;$(id).replaceChildren(...s.nodes.map(n=>{const o=document.createElement('option');o.value=n.id;o.textContent=n.id+' '+n.name;return o;}));if(by[old])$(id).value=old;}$('undo').disabled=!history.length;hint();}
function hint(){const msgs={move:'拖动圆点到对应建筑；拖动空白处平移底图，滚轮可缩放。',node:'点击底图放置一个新节点，然后在右侧填写名称与类别。',edge:first?'已选 '+first+'，请点击另一个节点。':'依次点击两个节点建立连线。',erase:'点击需要删除的连线；也可在右侧选择端点断开。'};$('hint').textContent=msgs[mode];}
function coord(e){const p=$('map').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('scene').getScreenCTM().inverse());}
function onNode(e,n){e.stopPropagation();e.preventDefault();selected=n.id;if(mode==='edge'){if(first&&first!==n.id){edge(first,n.id,true);first=null;}else first=n.id;draw();return;}if(mode==='move'){checkpoint();drag={type:'node',id:n.id};$('map').setPointerCapture(e.pointerId);}draw();}
function edge(a,b,add){if(!a||!b||a===b){$('hint').textContent='请选择两个不同节点。';return;}const exists=S().edges.some(e=>key(e.a,e.b)===key(a,b));if(exists===add){$('hint').textContent=add?'这两个节点已经相连。':'这两个节点没有连线。';return;}checkpoint();if(add)S().edges.push({a,b});else S().edges=S().edges.filter(e=>key(e.a,e.b)!==key(a,b));save();draw();}
$('map').addEventListener('pointerdown',e=>{if(e.button!==0)return;if(mode==='node'){const p=coord(e);if(p.x<0||p.x>310||p.y<0||p.y>207)return;checkpoint();let n=1;while(S().nodes.some(x=>x.id==='N'+n))n++;selected='N'+n;S().nodes.push({id:selected,name:'新增节点',kind:'building',x:p.x,y:p.y});save();mode='move';draw();$('nodeName').focus();$('nodeName').select();}else if(mode==='move'){drag={type:'pan',x:e.clientX,y:e.clientY,pan:{...pan}};$('map').setPointerCapture(e.pointerId);}});
$('map').addEventListener('pointermove',e=>{if(!drag)return;if(drag.type==='node'){const p=coord(e),n=S().nodes.find(n=>n.id===drag.id);n.x=Math.max(3,Math.min(307,p.x));n.y=Math.max(3,Math.min(198,p.y));draw();}else{const m=$('map').getScreenCTM();pan={x:drag.pan.x+(e.clientX-drag.x)/m.a,y:drag.pan.y+(e.clientY-drag.y)/m.d};transform();}});
function finish(){if(drag?.type==='node')save();drag=null;}$('map').addEventListener('pointerup',finish);$('map').addEventListener('pointercancel',finish);
function setZoom(z){const next=Math.max(.7,Math.min(8,z));pan.x=155-(155-pan.x)*next/zoom;pan.y=103.5-(103.5-pan.y)*next/zoom;zoom=next;transform();}
$('map').addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom*(e.deltaY<0?1.12:1/1.12));},{passive:false});$('plus').onclick=()=>setZoom(zoom*1.25);$('minus').onclick=()=>setZoom(zoom/1.25);$('fit').onclick=()=>{zoom=1;pan={x:0,y:0};transform();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;first=null;draw();});
$('editor').onsubmit=e=>{e.preventDefault();const n=S().nodes.find(n=>n.id===selected);if(!n)return;const old=n.id,id=$('nodeId').value.trim();if(!id||id.length>60||id.includes('|')){$('editMessage').textContent='编号需为1—60个字符，不能包含 |。';return;}if(S().nodes.some(v=>v!==n&&v.id===id)){$('editMessage').textContent='本阶段已有编号 '+id+'，请使用不同编号。';return;}checkpoint();n.id=id;n.name=$('nodeName').value.trim()||id;n.kind=$('nodeKind').value;for(const edge of S().edges){if(edge.a===old)edge.a=id;if(edge.b===old)edge.b=id;}if(first===old)first=id;selected=id;save();draw();$('editMessage').textContent=old===id?'节点信息已保存。':'已将 '+old+' 改为 '+id+'，相关连线已同步保留。';};
$('deleteNode').onclick=()=>{if(!selected)return;checkpoint();S().nodes=S().nodes.filter(n=>n.id!==selected);S().edges=S().edges.filter(e=>e.a!==selected&&e.b!==selected);selected=null;save();draw();};$('addEdge').onclick=()=>edge($('edgeA').value,$('edgeB').value,true);$('removeEdge').onclick=()=>edge($('edgeA').value,$('edgeB').value,false);
$('undo').onclick=()=>{if(history.length){data=history.pop();selected=null;first=null;save();draw();}};
for(const [id,msg,fn] of [['clearEdges','清空当前阶段的全部连线？节点仍保留。',()=>S().edges=[]],['clearNodes','清空当前阶段的全部节点和连线？可以撤销。',()=>{S().nodes=[];S().edges=[];}],['reset','恢复当前阶段初稿？当前修改可以撤销。',()=>data.stages[phase]=clone(INITIAL.stages[phase])]])$(id).onclick=()=>{if(confirm(msg)){checkpoint();fn();selected=null;first=null;save();draw();}};
for(const id of ['showEdges','showNodes','opacity'])$(id).oninput=draw;
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString(),note:'四阶段原图校正；年代未确认'},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='MIT_四阶段底图修改.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>2000000)throw Error('文件过大');const v=validate(JSON.parse(await file.text()));checkpoint();data=v;selected=null;save();draw();$('hint').textContent='已导入四个阶段的修改；可撤销。';}catch(e){$('hint').textContent='导入失败：'+e.message;}$('file').value='';};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){first=null;mode='move';draw();}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('undo').click();}});
$('referenceImage').src=REFERENCE_IMAGE;$('referenceOpen').onclick=()=>$('referenceDialog').showModal();$('referenceClose').onclick=()=>$('referenceDialog').close();
$('applyAlignment').onclick=()=>{checkpoint();alignCoordinates(data);save();draw();$('saved').textContent='已应用四阶段校正坐标；连线与自建节点保留，可撤销。';};
$('backupExport').onclick=()=>{let s;try{s=localStorage.getItem(KEY+'-before-alignment');}catch{}if(!s){$('saved').textContent='本机没有校正前存档。';return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'application/json'}));a.download='MIT_坐标校正前存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('upgradeBackup').onclick=()=>{let s;try{s=localStorage.getItem(KEY+'-before-id-edit');}catch{}if(!s){$('saved').textContent='本机没有升级前存档，请用“导出修改”备份当前数据。';return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'application/json'}));a.download='MIT_编号编辑升级前存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
window.mitEditor={snapshot:()=>clone(data),metrics:calc,selectPhase:switchPhase,validate,alignCoordinates};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_campus_graph',title:'读取当前校园图',description:'读取当前阶段节点、连线和指标，不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({phase:phase+1,graph:clone(S()),metrics:calc()})})).catch(()=>{});}catch{}}
draw();
